begin;
create table platform.applications (id uuid primary key default gen_random_uuid(), application_key text not null unique check (application_key = upper(application_key)), name text not null, description text, is_core boolean not null default false, status text not null default 'active' check (status in ('active','preview','retired')), launcher_path text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table iam.pages (id uuid primary key default gen_random_uuid(), application_id uuid not null references platform.applications(id) on delete cascade, page_key text not null, route_pattern text not null, name text not null, nav_group text, nav_order integer not null default 0, is_visible_in_nav boolean not null default true, unique (application_id, page_key), unique (application_id, route_pattern));
create table iam.permissions (id uuid primary key default gen_random_uuid(), permission_key text not null unique, application_id uuid references platform.applications(id) on delete cascade, page_id uuid references iam.pages(id) on delete cascade, action text not null check (action in ('read','create','update','delete','approve','export','manage','preview_portal')), description text);
create table iam.roles (id uuid primary key default gen_random_uuid(), organization_id uuid references platform.organizations(id) on delete cascade, application_id uuid references platform.applications(id) on delete cascade, role_key text not null, name text not null, scope text not null check (scope in ('platform','organization','application')), is_system boolean not null default false, is_read_only boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index roles_unique_platform on iam.roles (role_key) where organization_id is null;
create unique index roles_unique_org on iam.roles (organization_id, role_key) where organization_id is not null;
create table iam.role_permissions (role_id uuid not null references iam.roles(id) on delete cascade, permission_id uuid not null references iam.permissions(id) on delete cascade, primary key (role_id, permission_id));
create table iam.member_app_roles (id uuid primary key default gen_random_uuid(), organization_membership_id uuid not null references iam.organization_memberships(id) on delete cascade, organization_id uuid not null references platform.organizations(id) on delete cascade, company_id uuid references platform.companies(id) on delete cascade, application_id uuid not null references platform.applications(id) on delete cascade, role_id uuid not null references iam.roles(id) on delete restrict, valid_from timestamptz not null default now(), valid_until timestamptz, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), unique (organization_membership_id, company_id, application_id, role_id));
create table billing.plans (id uuid primary key default gen_random_uuid(), plan_key text not null unique, name text not null, interval text not null check (interval in ('month','year','custom')), price_minor bigint not null default 0 check (price_minor >= 0), currency_code char(3) not null default 'KES', status text not null default 'active' check (status in ('active','retired')), created_at timestamptz not null default now());
create table billing.application_subscriptions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete cascade, application_id uuid not null references platform.applications(id) on delete restrict, plan_id uuid references billing.plans(id) on delete restrict, status text not null check (status in ('trial','active','grace','past_due','suspended','cancelled')), trial_ends_at timestamptz, current_period_start timestamptz, current_period_end timestamptz, grace_ends_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_id, application_id));
commit;
